insert into public.kb_docs (key, team, kind, data) values
  ('drill:zb01', 'km', 'drill', $j${"id": "zb01", "name": "Canada Cup Drill I", "cat": "Passen", "min": 10, "desc": "• Die Übung startet auf beiden Seiten gleichzeitig.\n• X1 startet mit einem Torschuss und holt anschließend einen Puck aus der Ecke. O1 führt auf der anderen Seite gleichzeitig dieselbe Aktion aus.\n• O2 stimmt sein Timing auf X1 ab und erhält den Pass von X1.\n• O3 startet mit entsprechendem Timing, erhält den Pass von O2 und zieht anschließend zum Tor für den Abschluss.\n• Danach holt O3 einen neuen Puck aus der Ecke", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/01.webp"}$j$::jsonb),
  ('drill:zb02', 'km', 'drill', $j${"id": "zb02", "name": "Canada Cup Drill Reverse", "cat": "Passen", "min": 10, "desc": "• X1 startet mit einem Torschuss und holt anschließend einen Puck hinter dem Tor. O1 macht auf der anderen Seite dasselbe.\n• O2 startet mit richtigem Timing und erhält den Pass von X1.\n• O3 stimmt seinen Laufweg auf O2 ab, erhält den Pass von O2 und zieht zum Tor für den Abschluss.\n• Anschließend holt O3 einen neuen Puck hinter dem Tor", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/02.webp"}$j$::jsonb),
  ('drill:zb03', 'km', 'drill', $j${"id": "zb03", "name": "CAN NZ WarmUp Give & Go", "cat": "Aufwärmen", "min": 10, "desc": "STRAIGHT\n• Spieler 1 startet mit dem Puck in Richtung Spieler 2 und spielt einen Pass zu Spieler 2.\n• Spieler 1 fährt weiter und überquert die rote Linie.\n• Sobald Spieler 1 die rote Linie überquert hat, erhält er den Pass von Spieler 2 zurück.\nREVERSE\n• Spieler 1 startet mit dem Puck in Richtung Spieler 2 und spielt einen Pass zu Spieler 2.\n• Spieler 1 fährt weiter und überquert die rote Linie.\n• Nach dem Überqueren der roten Linie wechselt Spieler 1 die Fahrtrichtung.\n• Spieler 1 erhält anschließend den Pass von Spieler 2 zurück.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/03.webp"}$j$::jsonb),
  ('drill:zb04', 'km', 'drill', $j${"id": "zb04", "name": "CAN NZ WarmUp Stop/Sprint/Shoot", "cat": "Aufwärmen", "min": 10, "desc": "Variante 1\n• Spieler 1 startet und fährt bis zur blauen Linie, wo er einen Stopp macht.\n• Anschließend fährt Spieler 1 weiter bis zur roten Linie und erhält dort einen Pass von Spieler 2.\n• Spieler 1 nimmt den Puck mit und schließt mit einem Torschuss ab.\nVariante 2\n• Spieler 1 startet vorwärts und wechselt anschließend in die Rückwärtsfahrt.\n• An der blauen Linie macht Spieler 1 einen Stopp.\n• Anschließend fährt er weiter bis zur blauen Linie und erhält dort einen Pass von Spieler 2.\n• Spieler 1 nimmt den Puck mit und schließt mit einem Torschuss ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/04.webp"}$j$::jsonb),
  ('drill:zb05', 'km', 'drill', $j${"id": "zb05", "name": "CZE 4 Shot Warm-Up", "cat": "Aufwärmen", "min": 10, "desc": "• Auf Pfiff startet Spieler 1, erhält einen Pass von Spieler 4 für einen schnellen Torschuss.\n• Nach dem Schuss sprintet er in die Ecke, um einen zweiten Puck aufzunehmen.\n• Gleichzeitig startet Spieler 2, fährt mit hohem Tempo rundum den Kreis, erhält einen Pass von Spieler 4 und schließt mit einem Torschuss ab. Nach seinem Schuss bleibt er am Tor stehen.\n• Spieler 3 startet zeitlich abgestimmt und läuft seine Route durch die neutrale Zone.\n• Sobald Spieler 1 den zweiten Puck aufgenommen hat, wird er zum Passgeber und spielt einen Stretch-Pass zum Spieler 3, der seinen Torschuss abgibt.\n• Anschließend bleibt Spieler 3 am Tor stehen. Gemeinsam mit dem Spieler 2 bildet er einen Doppel-Screen vor dem Tor.\n• Spieler 1 sprintet anschließend zur blauen Linie.\n• Spieler 1 bekommt einen Pass von Spieler 4 auf anderen Seite. Anschließend gibt den vierten Torschuss ab, während die beiden Mitspieler vor dem Tor für den Screen sorgen.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/05.webp"}$j$::jsonb),
  ('drill:zb06', 'km', 'drill', $j${"id": "zb06", "name": "ITA Skating Deep - Cross-Ice Pass", "cat": "Passen", "min": 10, "desc": "1. Spieler 1 spielt einen Pass in die diagonale Ecke und fährt anschließend tief in die Zone, wobei er Geschwindigkeit aufnimmt.\n2. Aus der Ecke wird ein Breakout-Pass gespielt.\n3. Der Empfänger nimmt den Pass auf, überquert die blaue Linie und spielt einen Querpass zur gegenüberliegenden blauen Linie.\n4. Der Mitspieler spielt den Puck zurück. Dabei muss darauf geachtet werden, dass der angreifende Spieler im Abseitsbereich nicht vor dem Puck die blaue Linie überquert.\n5. Anschließend greifen die Spieler mit Tempo an und schließen mit einem Torschuss ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/06.webp"}$j$::jsonb),
  ('drill:zb07', 'km', 'drill', $j${"id": "zb07", "name": "ITA Skating Deep - Touch Pass", "cat": "Passen", "min": 10, "desc": "1. Spieler 1 spielt einen Pass in die diagonale Ecke und fährt anschließend tief in die Zone, wobei er Geschwindigkeit aufnimmt.\n2. Aus der Ecke wird ein Breakout-Pass gespielt.\n3. Der Empfänger spielt einen direkten Doppelpass (Give & Go) mit dem Spieler an der blauen Linie.\n4. Anschließend greifen die Spieler mit Tempo an und schließen mit einem Torschuss ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/07.webp"}$j$::jsonb),
  ('drill:zb08', 'km', 'drill', $j${"id": "zb08", "name": "Philadelphia WarmUp Drill", "cat": "Aufwärmen", "min": 10, "desc": "• Spieler 1 läuft mit Puck Richtung Mitte und spielt einen Pass zu Spieler 2 auf der gegenüberliegenden Seite.\n• Spieler 1 läuft weiter, erhält den Return-Pass und spielt anschließend zum nächsten Spieler.\n• Durch kontinuierliches Passspiel und Positionswechsel bewegen sich die Spieler mit Tempo durch die neutrale Zone.\n• Nach dem letzten Pass erfolgt der Zoneneintritt mit Torabschluss.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/08.webp"}$j$::jsonb),
  ('drill:zb09', 'km', 'drill', $j${"id": "zb09", "name": "Philadelphia WarmUp Drill Full", "cat": "Aufwärmen", "min": 10, "desc": "• Die Spieler starten, laufen um den nahen Bullypunkt in der neutralen Zone und zurück Richtung ihrer Startecke.\n• Dort spielen sie einen One-Touch-Doppelpass mit dem nächsten Spieler in der Reihe.\n• Anschließend laufen sie quer durch den Slot und spielen einen weiteren One-Touch-Doppelpass mit dem ersten Spieler der gegenüberliegenden Reihe.\n• Der Spieler in der Ecke nimmt danach den Puck mit, zieht zur Eismitte und passt zum Spieler entlang der Bande.\n• Dieser läuft mit dem Puck Richtung Tor und schließt mit einem Torschuss ab.\n• Der Passgeber läuft weiter um den Bullypunkt in der neutralen Zone und setzt die Übung fort.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/09.webp"}$j$::jsonb),
  ('drill:zb10', 'km', 'drill', $j${"id": "zb10", "name": "POR WarmUp 1v1", "cat": "Aufwärmen", "min": 10, "desc": "1. Spieler 1 fährt mit dem Puck hinter dem Tor entlang.\n2. Spieler 1 spielt einen Breakout-Pass zum Spieler 2.\n3. Spieler 2 spielt einen Stretch-Pass zum Spieler 3.\n4. Spieler 3 nimmt den Puck mit, greift an und schließt mit einem Torschuss ab.\n5. Anschließend wechseln die Spieler ihre Positionen:\n   1. Spieler 1 → Position 2\n   2. Spieler 2 → Position 3\n   3. Spieler 3 → Position 1", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/10.webp"}$j$::jsonb),
  ('drill:zb11', 'km', 'drill', $j${"id": "zb11", "name": "SUI NZ WarmUp 1", "cat": "Aufwärmen", "min": 10, "desc": "• Spieler 1 startet mit dem Puck und spielt einen Pass zu Spieler 2.\n• Spieler 2 spielt den Puck direkt zu Spieler 1 zurück.\n• Spieler 1 fährt über die rote Linie und spielt anschließend einen Pass zu Spieler 3.\n• Spieler 1 fährt weiter bis zur blauen Linie, berührt diese, wechselt die Fahrtrichtung und erhält anschließend den Pass von Spieler 3 zurück.\n• Spieler 1 nimmt den Puck mit und schließt mit einem Torschuss ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/11.webp"}$j$::jsonb),
  ('drill:zb12', 'km', 'drill', $j${"id": "zb12", "name": "SUI NZ WarmUp 2", "cat": "Aufwärmen", "min": 10, "desc": "• Spieler 1 startet mit dem Puck und spielt einen Pass zu Spieler 2.\n• Spieler 2 spielt den Puck direkt zu Spieler 1 zurück.\n• Spieler 1 fährt über die rote Linie und spielt anschließend einen Pass zu Spieler 3.\n• Spieler 1 fährt weiter bis zur blauen Linie, berührt diese, wechselt die Fahrtrichtung Richtung Mittelkreis und erhält anschließend den Pass von Spieler 3 zurück.\n• Spieler 1 nimmt den Puck mit und schließt mit einem Torschuss ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/12.webp"}$j$::jsonb),
  ('drill:zb13', 'km', 'drill', $j${"id": "zb13", "name": "SUI NZ WarmUp 3", "cat": "Aufwärmen", "min": 10, "desc": "• Spieler 1 startet mit dem Puck und spielt einen Pass zu Spieler 2.\n• Spieler 2 spielt den Puck direkt zu Spieler 1 zurück.\n• Spieler 1 fährt über die rote Linie und spielt anschließend einen Pass zu Spieler 3.\n• Spieler 1 fährt weiter bis zur blauen Linie, rundum den Spieler 3 und Spieler 4, und erhält anschließend den Pass von Spieler 3 zurück.\n• Spieler 1 nimmt den Puck mit und schließt mit einem Torschuss ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/13.webp"}$j$::jsonb),
  ('drill:zb14', 'km', 'drill', $j${"id": "zb14", "name": "RUS Net 2v1(2)", "cat": "Angriff", "min": 10, "desc": "• Coach/Spieler spielt den Puck tief in die Zone. Stürmer und Verteidiger starten zum Puck.\n• Der Verteidiger nimmt den Puck auf, macht einen Schulterblick und nutzt das Tor, um sich vom Forechecker zu lösen.\n• Danach spielt er einen Breakout-Pass auf einen der beiden Flügelspieler.\n• Die Flügelspieler starten anschließend ein 2-gegen-1 gegen den Verteidiger.\n• Der Forechecker verlässt die Übung und stellt sich wieder an.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/14.webp"}$j$::jsonb),
  ('drill:zb15', 'km', 'drill', $j${"id": "zb15", "name": "SUI NZ Angle Drill", "cat": "Passen", "min": 10, "desc": "1. Auf den Pfiff wird Puck zum gegenüberstehenden Spieler gespielt.\n2. Der Spieler, der den Pass gespielt hat, setzt anschließend nach und arbeitet daran, den puckführenden Spieler nach außen zur Bande zu lenken.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/15.webp"}$j$::jsonb),
  ('drill:zb16', 'km', 'drill', $j${"id": "zb16", "name": "SUI NZ WarmUp 4 2v0", "cat": "Aufwärmen", "min": 10, "desc": "• Set players up behind the the face-off dots just inside the blueline.\n• On the whistle, two opposite lines skate towards the other line across from them and make a pass just before the red line.\n• After the pass, the player curls back up ice along the boards, while the player with the puck skates up center ice.\n• The puck carrier drives towards the players waiting in line and kicks the puck out to the boards just before the blue line.\n• The player that was skating along the boards, receives the puck and then drives towards the middle of the ice and fires a shot on net.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/16.webp"}$j$::jsonb),
  ('drill:zb17', 'km', 'drill', $j${"id": "zb17", "name": "RUS Warm-Up 1v0/2v0", "cat": "Aufwärmen", "min": 10, "desc": "• Spieler 1 startet rückwärts\n• Spieler 1 erhält einen Pass von der eigenen Linie.\n• Spieler 1 spielt den Puck direkt zurück (Touch Pass).\n• Spieler 1 öffnet sich durch einen Richtungswechsel und erhält anschließend den Pass von der anderen Linie.\n• Der Passgeber schließt sich dem Angriff an – es entsteht eine 2-gegen-0-Situation.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/17.webp"}$j$::jsonb),
  ('drill:zb18', 'km', 'drill', $j${"id": "zb18", "name": "RUS 2v2 Wave", "cat": "Spielformen", "min": 10, "desc": "• Auf den ersten Pfiff wechseln die beiden weit entfernten Stürmer ihre Laufbahnen. Dabei können sie sich auch einen Puck zuspielen, bevor sie den Angriff starten.\n• Der Angriff muss von außerhalb der Bullypunkte in der neutralen Zone erfolgen.\n• Die Verteidiger rücken in die neutrale Zone vor, um einen kontrollierten Abstand (Gap) aufzubauen und mit der hohen Geschwindigkeit der Stürmer umzugehen.\n• Das 2-gegen-2 wird ausgespielt, bis der Trainer einen zweiten Pfiff gibt.\n• Auf den zweiten Pfiff ist der erste Stürmerblock fertig. Die beiden Stürmer an der näheren blauen Linie starten und fahren um die gegenüberliegenden Bullypunkte, bevor sie den Angriff auf die Verteidiger beginnen.\n• Die Verteidiger aus dem ersten 2-gegen-2 fahren anschließend zurück und bauen gegen die zweite Gruppe von Stürmern erneut den richtigen Abstand (Gap) auf.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/18.webp"}$j$::jsonb),
  ('drill:zb19', 'km', 'drill', $j${"id": "zb19", "name": "RUS Cycling Drill 1v0", "cat": "Angriff", "min": 10, "desc": "1. Der erste Spieler fährt mit dem Puck entlang der Bande und spielt den Puck anschließend zurück in Richtung Ecke (Cycle).\n2. Spieler 2 kommt tief entgegen, nimmt den Puck auf und fährt weiter in die Ecke. Anschließend spielt er den Puck vor das Tor.\n3. Nach dem Cycle zieht Spieler 1 zum Tor und schließt mit einem Torschuss ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/19.webp"}$j$::jsonb),
  ('drill:zb20', 'km', 'drill', $j${"id": "zb20", "name": "Buffalo 2 vs 2 Board pass", "cat": "Spielformen", "min": 10, "desc": "• Auf den Pfiff starten beide Seiten gleichzeitig.\n• Spieler 1 und 2 starten gemeinsam mit einem Give-and-Go (Doppelpass).\n• Spieler 1 spielt einen Banden-Pass zu Spieler 2.\n• Spieler 2 zieht Richtung Tor und schließt mit einem Torschuss ab.\n• Spieler 1 läuft durch die Mitte zum Tor und geht auf einen möglichen Rebound.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/20.webp"}$j$::jsonb),
  ('drill:zb21', 'km', 'drill', $j${"id": "zb21", "name": "Calgary 3x Shooting Drill", "cat": "Schuss", "min": 10, "desc": "• Spieler 1 startet, läuft um den Bullykreis und passt zu Spieler 2, der aus der Ecke startet.\n• Spieler 1 läuft weiter bis zur blauen Linie, dreht zurück in die Angriffszone, erhält einen Pass von Gruppe 2 und schließt aufs Tor ab.\n• Spieler 2 passt zum Verteidiger in der neutralen Zone, läuft quer über das Eis und erhält einen Bankpass über die Bande zurück.\n• Anschließend zieht er zum Torabschluss.\n• Danach holt Spieler 2 einen neuen Puck aus der Ecke und passt zum Verteidiger an der blauen Linie.\n• Der Verteidiger schließt die Übung mit einem Schuss von der blauen Linie ab.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/21.webp"}$j$::jsonb),
  ('drill:zb22', 'km', 'drill', $j${"id": "zb22", "name": "Slovakian Regroup", "cat": "Aufbau", "min": 10, "desc": "• Beide Verteidiger starten nach links, machen an der roten Linie einen Pivot von vorwärts auf rückwärts und erhalten einen Pass (Pass 1).\n• Der Verteidiger läuft rückwärts, öffnet sich, dreht auf vorwärts und spielt einen Pass zum Stürmer (Pass 2).\n• Der Stürmer löst sich von der Bande, nimmt den Pass an und zieht zum Torabschluss.\n• Der rote Verteidiger wiederholt den Ablauf auf der anderen Seite, erhält einen Pass vom zweiten Stürmer (Pass 3) und spielt nach einem Pivot zur gegenüberliegenden Seite (Pass 4).\n• Anschließend rückt der Verteidiger bis zur blauen Linie auf und erhält einen weiteren Pass aus der Reihe (Pass 5).", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/22.webp"}$j$::jsonb),
  ('drill:zb23', 'km', 'drill', $j${"id": "zb23", "name": "GER Weak Side Attack 2v1 to 3v2", "cat": "Angriff", "min": 10, "desc": "Teil 1 – 2 gegen 1\n• Auf den Pfiff kreuzen die beiden Stürmer ihre Laufbahnen und spielen sich dabei den Puck zu.\n• Anschließend fahren sie gemeinsam ins Angriffsdrittel und greifen an. (2v1)\n• Gleichzeitig startet ein dritter Stürmer mit einem Puck entlang der blauen Linie.\nTeil 2 – 3 gegen 2\n• Auf den nächsten Pfiff wird das 2v1 beendet und der zweite Puck wird aktiv.\n• Der dritte Stürmer soll möglichst über die schwache Seite angreifen, um Zeit und Raum zu gewinnen und seinen Mitspielern zu ermöglichen, sich dem Angriff anzuschließen.\n• Gleichzeitig starten zwei neue Verteidiger von der Mittellinie.\n• Dadurch entsteht eine 3v2-Situation, die ausgespielt wird.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/23.webp"}$j$::jsonb),
  ('drill:zb24', 'km', 'drill', $j${"id": "zb24", "name": "Basic Breakout 3 vs 2 Weak-/Strong Side", "cat": "Aufbau", "min": 10, "desc": "", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/24.webp"}$j$::jsonb),
  ('drill:zb25', 'km', 'drill', $j${"id": "zb25", "name": "3 vs 2 Regroup/Breakout", "cat": "Aufbau", "min": 10, "desc": "1. Coach ) startet mit Pass zur Verteidigung -\n2. Stürmer e machen regroup\n3. Verteidiger - bewegen sich auf die Seite zur Scheibe\n4. Stürmer e dump die Scheibe\n5. Verteidiger - und Stürmer e starten Breakout über die weak Seite\n6. Angriff 3 vs 2 oder 5 vs 2", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/25.webp"}$j$::jsonb),
  ('drill:zb26', 'km', 'drill', $j${"id": "zb26", "name": "4 v 2 Continuous Zone Entry", "cat": "Angriff", "min": 10, "desc": "• 4 offensive Spieler greifen gegen 2 Verteidiger an.\n• Die Offensive versucht, direkt aus dem Angriff zu scoren. Gelingt das nicht, bleibt sie in Puckbesitz und baut einen neuen Angriff auf.\n• Die Defensive versucht, den Puck zu erobern und zu den eigenen Mitspielern außerhalb der Zone zu passen.\n• Die Aktion endet mit dem Pfiff des Coaches oder einem erfolgreichen Pass der Defensive aus der Zone.\n• Sofort greifen die nächsten 4 Spieler an. 2 Spieler des vorherigen Offensivteams bleiben als Verteidiger in der Zone.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/26.webp"}$j$::jsonb),
  ('drill:zb27', 'km', 'drill', $j${"id": "zb27", "name": "Dallas DZ Coverage", "cat": "Defensive", "min": 10, "desc": "• Die Übung startet mit einem Low-to-High-Spiel in der Angriffszone und wird im 5-gegen-5 ausgespielt.\n• Auf den Pfiff wechseln die 5 offensiven Spieler sofort in den Backcheck und ziehen sich in den House-Bereich vor dem eigenen Tor zurück.\n• Gleichzeitig stehen 5 neue offensive Spieler bereit, um den Angriff zu starten.\n• Auf den nächsten Pfiff beginnt ein neues 5-gegen-5, das frei ausgespielt wird.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/27.webp"}$j$::jsonb),
  ('drill:zb28', 'km', 'drill', $j${"id": "zb28", "name": "FIN 3v2 to 5v5 Backcheck", "cat": "Defensive", "min": 10, "desc": "• Teil 1: Auf den ersten Pfiff spielt der Coach einen Puck in die Ecke. Drei offensive Spieler starten ein 3-gegen-2 im tiefen Bereich. Die Offensive versucht, eine Torchance zu kreieren und abzuschließen. Die Defensive versucht, den Angriff zu unterbinden und den Puck zu erobern.\n• Teil 2: Auf den zweiten Pfiff spielt der Coach einen neuen Puck zu einem der drei hohen Stürmer, die nicht am ersten 3-gegen-2 beteiligt sind. Dadurch startet sofort ein 3-gegen-2 in die entgegengesetzte Richtung. Die Spieler aus dem ersten 3-gegen-2 schalten schnell um, gehen in den Backcheck und versuchen, wieder ins Spiel einzugreifen.\n• Teil 3: Sobald die nachrückenden Spieler wieder im Spiel sind, entsteht ein volles 5-gegen-5. Die Offensive versucht, eine Torchance herauszuspielen und ein Tor zu erzielen. Die Defensive arbeitet an Zuordnung, Kommunikation, Puckeroberung und schnellem Umschalten.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/28.webp"}$j$::jsonb),
  ('drill:zb29', 'km', 'drill', $j${"id": "zb29", "name": "Montreal Forecheck", "cat": "Forecheck", "min": 10, "desc": "• Der Coach spielt einen Dump-In für das schwarze Team in die Zone.\n• Das schwarze Team organisiert einen schnellen oder kontrollierten Breakout und verlässt die eigene Zone.\n• Nach dem Zonenaustritt passt das schwarze Team den Puck zum roten Team.\n• Das rote Team läuft bis zur roten Linie, spielt den Puck tief in die gegnerische Zone (Chip-In) und startet einen aggressiven Forecheck im 5-gegen-5.\n• Anschließend wird die Spielsituation im 5-gegen-5 ausgespielt.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/29.webp"}$j$::jsonb),
  ('drill:zb30', 'km', 'drill', $j${"id": "zb30", "name": "RUS Rush Forcheck", "cat": "Forecheck", "min": 10, "desc": "1. Auf den Pfiff starten beide Teams gleichzeitig.\n2. Die Offensive skatet von der roten zur blauen Linie.\n3. Die Defensive skatet von der blauen zur roten Linie.\n4. Sobald beide Gruppen ihre jeweilige Linie erreicht haben, spielt der Coach einen Puck in die Ecke.\n5. Beide Teams reagieren sofort auf den Puck und es beginnt ein 5v5.\n6. Die Offensive versucht, Puckbesitz aufzubauen und zum Torabschluss zu kommen, während die Defensive verteidigt und versucht, den Puck zurückzugewinnen bzw. aus der Zone zu spielen.\nSkating-Varianten:\n1. Forward → Forward: gesamte Strecke vorwärts.\n2. Backward → Backward: gesamte Strecke rückwärts.\n3. Backward → Forward: rückwärts starten, anschließend Pivot/Transition auf vorwärts und zur Ziellinie weiter skaten.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/30.webp"}$j$::jsonb),
  ('drill:zb31', 'km', 'drill', $j${"id": "zb31", "name": "CZE 2v2 Continuous", "cat": "Spielformen", "min": 10, "desc": "• Auf den ersten Pfiff passt der blaue Spieler zum roten Spieler.\n• Der rote Spieler muss zuerst die blaue Linie verlassen, bevor er zum 1-gegen-1 in die Zone angreift.\n• Der blaue Spieler versucht, durch Vorwärtsskaten und gutes Angling den Angreifer nach außen abzudrängen.\n• Auf den zweiten Pfiff startet am anderen Eisende ein neues 1-gegen-1 nach demselben Prinzip.\n• Gleichzeitig beenden die Spieler des ersten 1-gegen-1 ihre Aktion und laufen zum anderen Eisende, um ihre Mitspieler zu unterstützen.\n• Dadurch entsteht ein 2-gegen-2, das kontinuierlich weitergespielt wird.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/31.webp"}$j$::jsonb),
  ('drill:zb32', 'km', 'drill', $j${"id": "zb32", "name": "Oreo 3 vs 3", "cat": "Spielformen", "min": 10, "desc": "• Puck in die Zone und das 3-gegen-3 beginnt.\n• Die Offensive versucht ein Tor zu erzielen, während die Defensive den Puck erobern und zu den nächsten Spielern in der Reihe zu passen.\n• Gelingt der Pass, werden die neuen Spieler sofort zur Offensive. Das bisherige Offensivteam wechselt direkt in die Defensive.\n• Das Spiel läuft ohne Unterbrechung kontinuierlich weiter.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/32.webp"}$j$::jsonb),
  ('drill:zb33', 'km', 'drill', $j${"id": "zb33", "name": "USA Breakout Game 4v2", "cat": "Aufbau", "min": 10, "desc": "• Der Coach od Spieler startet die Übung mit einem Dump-In ins gegenüberliegende Drittel.\n• Alle Power-Play-Spieler laufen zurück in die eigene Zone, organisieren den Breakout und versuchen anschließend ein Tor zu erzielen.\n• Die Penalty-Kill-Spieler üben einen aggressiven PK-Forecheck und versuchen den Spielaufbau zu stören.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/33.webp"}$j$::jsonb),
  ('drill:zb34', 'km', 'drill', $j${"id": "zb34", "name": "USA Breakouts to 3 Forecheckers (5 vs 5)", "cat": "Aufbau", "min": 10, "desc": "• Der Verteidiger läuft rückwärts auf vorwärts und holt den Puck.\n• Die Stürmer starten einen strukturierten Breakout: Der Center unterstützt tief und kontrolliert, die Flügel kommen über die Bullypunkte.\n• Optional: Bevor der Puck zu einem der drei Forechecker gespielt wird, müssen 3, 4 oder alle 5 Spieler den Puck berührt haben.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/34.webp"}$j$::jsonb),
  ('drill:zb35', 'km', 'drill', $j${"id": "zb35", "name": "Breakout Quick (Grün)", "cat": "Aufbau", "min": 10, "desc": "Phase 1\n1. Spieler 1 schließt mit einem Torschuss ab.\n2. Spieler 1 holt eine neue Scheibe.\n3. Spieler 1 spielt einen Pass zu Spieler 2.\n4. Spieler 1 stellt sich anschließend auf der gegenüberliegenden Seite an.\nPhase 2\n1. Spieler 1 schließt mit einem Torschuss ab.\n2. Spieler 1 holt eine neue Scheibe.\n3. Spieler 1 spielt einen Pass zu Spieler 2.\n4. Spieler 2 spielt den Puck weiter zu Spieler 3.\n5. Spieler 1 übernimmt die Position von Spieler 2. Spieler 2 stellt sich anschließend auf der gegenüberliegenden Seite an.\nPhase 3\n1. Spieler 1 schließt mit einem Torschuss ab.\n2. Spieler 2 und Spieler 3 starten. Gleichzeitig holt Spieler 1 eine neue Scheibe.\n3. Spieler 1 spielt einen Pass zu Spieler 2.\n4. Spieler 2 spielt den Puck zu Spieler 3.\n5. Spieler 3 schließt mit einem Torschuss ab und startet anschließend die gleiche Übung auf der gegenüberliegenden Seite.\n6. Nach Abschluss der Aktion wechseln die Spieler ihre Positionen:\n   1. Spieler 1 wird zu Spieler 2.\n   2. Spieler 2 wird zu Spieler 3.\n   3. Spieler 3 wird zu Spieler 1.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/35.webp"}$j$::jsonb),
  ('drill:zb36', 'km', 'drill', $j${"id": "zb36", "name": "Breakout Wheel (Gelb)", "cat": "Aufbau", "min": 10, "desc": "Phase 1\n1. Spieler 1 schließt mit einem Torschuss ab.\n2. Spieler 1 holt hinter dem Tor eine neue Scheibe.\n3. Spieler 1 spielt einen Pass zu Spieler 2.\n4. Anschließend stellt sich Spieler 1 auf der gegenüberliegenden Seite an.\nPhase 2\n1. Spieler 1 schließt mit einem Torschuss ab.\n2. Spieler 1 holt hinter dem Tor eine neue Scheibe.\n3. Spieler 1 spielt einen Pass zu Spieler 2.\n4. Spieler 2 spielt den Puck weiter zu Spieler 3.\n5. Spieler 1 übernimmt die Position von Spieler 2. Spieler 2 stellt sich anschließend auf der gegenüberliegenden Seite an.\nPhase 3\n1. Spieler 1 schließt mit einem Torschuss ab.\n2. Spieler 2 und Spieler 3 starten. Gleichzeitig holt Spieler 1 hinter dem Tor eine neue Scheibe.\n3. Spieler 1 spielt einen Pass zu Spieler 2.\n4. Spieler 2 spielt einen Pass zu Spieler 3.\n5. Spieler 3 schließt mit einem Torschuss ab und eröffnet anschließend den gleichen Ablauf auf der gegenüberliegenden Seite.\n6. Anschließend wechseln die Spieler ihre Positionen:\n   1. Spieler 1 wird zu Spieler 2.\n   2. Spieler 2 wird zu Spieler 3.\n   3. Spieler 3 wird zu Spieler 1.", "photo": "https://valle26.github.io/Gunners/kabine/uebungen/36.webp"}$j$::jsonb)
