-- =====================================================================
--  Drills Book EC Zirl 2026/27: 36 Übungen für die Kabine der Kampfmannschaft
--  Supabase -> SQL Editor -> New query -> alles einfügen -> Run
--  Die bisherigen Probe-Übungen der Kampfmannschaft werden gelöscht.
--  Die Bilder liegen im Repository Gunners unter kabine/uebungen/.
-- =====================================================================
delete from public.kb_docs where team = 'km' and kind = 'drill';

on conflict (key) do update set data = excluded.data, team = excluded.team, kind = excluded.kind;

-- Kategorien für die Übungen
values ('meta:cats', 'km', 'meta', $j${"list": ["Aufwärmen", "Passen", "Schuss", "Aufbau", "Angriff", "Forecheck", "Defensive", "Spielformen", "Skating", "Special Teams", "Kondition", "Goalie"]}$j$::jsonb)
on conflict (key) do update set data = excluded.data;

-- Kontrolle
select data->>'name' as uebung, data->>'cat' as kategorie, data->>'min' as minuten
from public.kb_docs where team = 'km' and kind = 'drill' order by key;
